# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Define the columns
unit_columns = ["unit1", "unit2", "unit3", "unit4", "unit5"]
residuals_col = "residuals"
target_col = "I"

# Find the header row and data rows
header_row = None
data_rows = []

for row in ws.iter_rows(min_row=1, max_row=21, values_only=True):
    if "unit1" in row and "unit2" in row and "unit3" in row and "unit4" in row and "unit5" in row and residuals_col in row:
        header_row = row
        break
    data_rows.append(row)

# Extract the min and max values for each unit
min_values = {}
max_values = {}

for row in data_rows:
    if row[0] == "min":
        for i, val in enumerate(row[1:6]):
            min_values[unit_columns[i]] = val
    elif row[0] == "max":
        for i, val in enumerate(row[1:6]):
            max_values[unit_columns[i]] = val

# Extract the data rows excluding the min and max rows
data_rows = [row for row in data_rows if row[0] not in ["min", "max"]]

# Convert the data rows into a list of dictionaries for easier manipulation
data = []
for row in data_rows:
    entry = {}
    for i, col in enumerate(unit_columns):
        entry[col] = row[i]
    entry[residuals_col] = row[6]
    data.append(entry)

# Function to adjust units to balance residuals
def adjust_units(entry):
    residual = entry[residuals_col]
    units = [entry[unit] for unit in unit_columns]
    min_vals = [min_values[unit] for unit in unit_columns]
    max_vals = [max_values[unit] for unit in unit_columns]

    # Determine the direction of adjustment
    if residual > 0:
        # Add to units from unit1 to unit5
        for i in range(len(units)):
            if residual <= 0:
                break
            if units[i] == 0:
                continue
            add = min(residual, max_vals[i] - units[i])
            units[i] += add
            residual -= add
    else:
        # Subtract from units from unit5 to unit1
        for i in reversed(range(len(units))):
            if residual >= 0:
                break
            if units[i] == 0:
                continue
            subtract = min(-residual, units[i] - min_vals[i])
            units[i] -= subtract
            residual += subtract

    # Update the entry with adjusted units
    for i, unit in enumerate(unit_columns):
        entry[unit] = units[i]

    return entry

# Apply the adjustment to each entry
adjusted_data = [adjust_units(entry) for entry in data]

# Write the adjusted data back to the worksheet
for i, entry in enumerate(adjusted_data):
    row_idx = i + 2  # Start from row 2
    for j, unit in enumerate(unit_columns):
        ws.cell(row=row_idx, column=j + 1, value=entry[unit])
    ws.cell(row=row_idx, column=9, value=0)  # Set column I to 0

# Save the workbook
wb.save("output.xlsx")
