from openpyxl import load_workbook
from datetime import datetime, timedelta
import calendar

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Find the header row and first data row
header_row = None
data_start_row = None

for row in ws.iter_rows(min_row=1, max_row=10):
    for cell in row:
        if cell.value == "Year":
            header_row = cell.row
            break
    if header_row:
        break

# Find the year column (2016)
year_col = None
for col in ws.iter_cols(min_row=header_row, max_row=header_row + 1):
    for cell in col:
        if cell.value == "2016":
            year_col = cell.column
            break
    if year_col:
        break

# Find the month headers (Jan to Dec)
month_headers = []
for col in ws.iter_cols(min_row=header_row + 1, max_row=header_row + 1):
    for cell in col:
        if cell.value in ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]:
            month_headers.append((cell.column, cell.value))
    if len(month_headers) == 12:
        break

# Find the night shift row
night_shift_row = None
for row in ws.iter_rows(min_row=header_row + 2, max_row=header_row + 3):
    for cell in row:
        if cell.value == "Night shift":
            night_shift_row = cell.row
            break
    if night_shift_row:
        break

# Extract night shift data for the year 2016
year_2016_col = year_col
night_shift_data = []
for month_col, month_name in month_headers:
    cell_value = ws.cell(row=night_shift_row, column=month_col).value
    if cell_value is not None:
        night_shift_data.append(cell_value)

# Calculate the total number of days in 2016
year_2016 = 2016
total_days_2016 = 366 if calendar.isleap(year_2016) else 365

# Calculate the percentage of night shifts
total_night_shifts = sum(night_shift_data)
percentage_night_shifts = total_night_shifts / total_days_2016

# Format the percentage according to the rules
if percentage_night_shifts == 0:
    formatted_percentage = int(percentage_night_shifts)
elif abs(percentage_night_shifts - round(percentage_night_shifts, 1)) < 1e-9:
    formatted_percentage = round(percentage_night_shifts, 1)
else:
    formatted_percentage = round(percentage_night_shifts, 9)

# Write the formatted percentage to the answer range (B11:M11)
for i, (col, month_name) in enumerate(month_headers):
    ws.cell(row=11, column=col, value=formatted_percentage)

# Save the workbook
wb.save("output.xlsx")
